import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Security and privacy audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/SECURITY-PRIVACY.html"}],["meta",{"property":"og:title","content":"Security and privacy audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/SECURITY-PRIVACY.html"}],["meta",{"name":"twitter:title","content":"Security and privacy audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/SECURITY-PRIVACY.md","filePath":"audits/SECURITY-PRIVACY.md","lastUpdated":1794198491000}`),a={name:`audits/SECURITY-PRIVACY.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="security-and-privacy-audit" tabindex="-1">Security and privacy audit <a class="header-anchor" href="#security-and-privacy-audit" aria-label="Permalink to “Security and privacy audit”">​</a></h1><h2 id="sec-01-—-imported-account-ids-are-interpolated-into-html-without-escaping" tabindex="-1">SEC-01 — Imported account IDs are interpolated into HTML without escaping <a class="header-anchor" href="#sec-01-—-imported-account-ids-are-interpolated-into-html-without-escaping" aria-label="Permalink to “SEC-01 — Imported account IDs are interpolated into HTML without escaping”">​</a></h2><p><strong>Current status: COMPLETED in PR #75.</strong> The account-card <code>data-id</code>, radio <code>value</code> and remove-button attribute now pass IDs through the shared HTML encoder. The ID itself is not restricted, preserving import compatibility. See <code>src/web/escape-html.js</code>, <code>src/web/app.js</code> and the adversarial security regression tests.</p><p><strong>Severity: P1</strong></p><p><strong>Evidence:</strong></p><ul><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/config-schema.js#L25-L26" target="_blank" rel="noreferrer">config-schema.js L25-L26</a> requires account IDs to be non-empty but does not constrain their characters.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L214" target="_blank" rel="noreferrer">app.js L214</a> parses an imported JSON file, validates its configuration and applies it.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L84" target="_blank" rel="noreferrer">app.js L84</a> uses each imported account object key as the account ID.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L63" target="_blank" rel="noreferrer">app.js L63</a> inserts <code>a.id</code> directly into <code>data-id</code>, radio <code>value</code> and <code>data-remove-account</code> attributes inside an <code>innerHTML</code> template. The local <code>esc</code> helper is used for labels but not for the ID.</li></ul><p><strong>Impact:</strong> a crafted JSON file can supply an account ID containing quotes/HTML and break out of an attribute when the user imports it. This is a client-side DOM-XSS path in the public application origin. It requires the victim to import a malicious scenario file, but the import feature is an explicit untrusted-file boundary.</p><p><strong>Recommendation:</strong></p><ol><li>Escape the ID for every HTML attribute context at render time (at minimum use the existing <code>esc(a.id)</code> consistently).</li><li>Prefer DOM construction and <code>setAttribute</code> over concatenating untrusted values into HTML.</li><li>Consider validating IDs against a documented safe identifier format, but do not rely on validation as a substitute for output encoding.</li><li>Add a regression test importing an account ID such as <code>&quot;&gt;&lt;img src=x onerror=alert(1)&gt;</code> and assert that it is rendered as inert text/attribute data.</li><li>Audit every <code>innerHTML</code> template for imported values and keep report rendering covered by adversarial-label tests.</li></ol><h2 id="positive-security-controls" tabindex="-1">Positive security controls <a class="header-anchor" href="#positive-security-controls" aria-label="Permalink to “Positive security controls”">​</a></h2><ul><li>Imported configuration is JSON-parsed and checked against an allowlisted schema before application.</li><li>Field values are generally inserted using <code>textContent</code> or HTML escaping; the account-ID path is the exception identified above.</li><li>The standalone report escapes dynamic table/ledger/instruction text and protects embedded JSON from closing the script element.</li><li>The worker is a dedicated application-owned worker. Its protocol validates message type, positive safe integer request ID and object payload; using <code>event.origin</code> as worker authentication was correctly avoided.</li><li>The browser app uses a local static catalogue and does not require a backend account/session service.</li><li>No third-party analytics, advertising pixels or session-replay scripts were identified in the reviewed web template.</li></ul><h2 id="priv-01-—-local-scenario-draft-deletion-and-retention" tabindex="-1">PRIV-01 — Local scenario draft deletion and retention <a class="header-anchor" href="#priv-01-—-local-scenario-draft-deletion-and-retention" aria-label="Permalink to “PRIV-01 — Local scenario draft deletion and retention”">​</a></h2><p><strong>Current status: IMPLEMENTED on this branch; CI passed.</strong> The UI states that draft data is stored only in the current browser until the user clears it. A visible <code>Clear saved draft</code> button requests confirmation and removes the <code>fd-cal:draft:v1</code> localStorage entry. The current form remains in the active tab; the status message explains that editing it will create a new saved draft. The click handler stops propagation so the surrounding form click-to-save handler cannot immediately recreate the deleted entry.</p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/web/app.js" target="_blank" rel="noreferrer">draft save/restore/clear logic</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/src/web/index.html" target="_blank" rel="noreferrer">retention notice and control</a>, <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/audit/rulesets-codebase-review/tests/js/web-controls-contract.test.js" target="_blank" rel="noreferrer">privacy regression contract</a>.</p><p><strong>Boundary:</strong> this control deletes FD Cal&#39;s saved draft key only. It does not clear browser history, downloads, exported JSON files, other sites&#39; storage, or the currently displayed in-memory form. No scenario data transmission or analytics was added.</p><p><strong>Acceptance:</strong> met on this branch. Retention is explained; deletion is user-initiated and confirmed; the deleted draft is not re-saved by the same click. CI passed; pending shipment to <code>dev</code>.</p><h2 id="web-sec-02-—-static-hosting-needs-an-explicit-security-header-strategy" tabindex="-1">WEB-SEC-02 — Static hosting needs an explicit security-header strategy <a class="header-anchor" href="#web-sec-02-—-static-hosting-needs-an-explicit-security-header-strategy" aria-label="Permalink to “WEB-SEC-02 — Static hosting needs an explicit security-header strategy”">​</a></h2><p><strong>Current status: OPEN / hosting constraint documented.</strong> FD Cal is published on GitHub.com Pages. The repository&#39;s static build and Pages artifact do not provide a configurable origin-server response-header policy. No verified response-header set for the production or dev origin has been established in this audit.</p><p><strong>Verified platform boundary:</strong></p><ul><li>GitHub describes Pages as a static hosting service that publishes HTML, CSS and JavaScript from a repository: <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages" target="_blank" rel="noreferrer">GitHub Pages overview</a>.</li><li>GitHub&#39;s Pages documentation states that custom MIME types cannot be configured per file or repository: <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/creating-a-github-pages-site" target="_blank" rel="noreferrer">Creating a GitHub Pages site</a>.</li><li>GitHub Enterprise Server has a separate administrator-level response-header configuration in its Management Console; that is not a setting available to this GitHub.com Pages repository: <a href="https://docs.github.com/en/enterprise-server@latest/admin/configuring-settings/configuring-user-applications-for-your-enterprise/configuring-github-pages-for-your-enterprise" target="_blank" rel="noreferrer">GitHub Enterprise Server response headers</a>.</li></ul><p>Do not treat a <code>_headers</code> file or workflow-generated artifact as proof that GitHub.com Pages emits custom response headers. Verify actual origin responses before recording any header as deployed.</p><p><strong>Controls and decision:</strong></p><ol><li>Keep all application assets same-origin and avoid adding third-party scripts, analytics or session replay without a separate review.</li><li>Keep the existing escaping, safe-link handling, noindex and crawler controls. They address different risks and are not substitutes for response headers.</li><li>If policy requires enforceable <code>Content-Security-Policy</code>, <code>Strict-Transport-Security</code>, <code>X-Content-Type-Options</code>, <code>X-Frame-Options</code> / <code>frame-ancestors</code>, or <code>Permissions-Policy</code>, put a CDN/reverse proxy or a host with response-header configuration in front of Pages, or migrate hosting.</li><li>Meta policies may provide limited defence-in-depth for supported directives, but they cannot fully replace response headers (for example, a CSP meta policy cannot enforce <code>frame-ancestors</code>).</li><li>Before closing this finding, capture <code>curl -I</code> evidence for production and dev origins and compare the returned headers against an approved policy. Do not claim a header is present based on repository configuration alone.</li></ol><p><strong>Acceptance:</strong> a hosting-layer decision is recorded, required headers are verified from actual HTTP responses, and the policy is tested on both production and <code>/dev/</code> paths. No hosting migration or security-header deployment is included in this branch.</p><h2 id="privacy-assessment" tabindex="-1">Privacy assessment <a class="header-anchor" href="#privacy-assessment" aria-label="Permalink to “Privacy assessment”">​</a></h2><ul><li>The browser copy states that calculations run locally and drafts stay in the browser.</li><li>The app&#39;s data flows are primarily local catalogue fetches, local storage and a same-origin worker.</li><li>The standalone report is generated client-side and can be saved as a local HTML file.</li><li>No remote analytics or session replay was found in the reviewed source.</li><li>A concise privacy notice should explain local storage, file import/export, local report generation, network requests for static catalogue assets, and how to clear saved data. Avoid generic legal boilerplate that does not match the actual product.</li></ul><h2 id="priv-02-—-public-privacy-notice-terms-and-preference-management" tabindex="-1">PRIV-02 — Public privacy notice, terms and preference management <a class="header-anchor" href="#priv-02-—-public-privacy-notice-terms-and-preference-management" aria-label="Permalink to “PRIV-02 — Public privacy notice, terms and preference management”">​</a></h2><p><strong>Current status: IMPLEMENTED on this branch; CI validation pending.</strong></p><ul><li>Added public Privacy Policy and Terms &amp; Conditions pages under the web application.</li><li>Added a first-visit privacy banner. A saved preference suppresses the banner on subsequent visits.</li><li>Added a footer control so users can reopen and change their preferences.</li><li>Necessary browser storage is displayed as always enabled. FD Cal currently uses local storage rather than setting its own cookies; the UI and policy distinguish these accurately.</li><li>Optional analytics preference is stored locally but is not connected to any analytics provider or tracking code. Selecting it does not enable collection. Any future analytics integration must identify its provider and data practices and honour the saved preference before sending optional analytics requests.</li><li>The legal pages explain local scenario processing, the local draft&#39;s indefinite retention until user deletion/browser clearing, in-memory worker execution, client-generated reports and exports, static asset requests, hosting-layer request logs, and the absence of a current FD Cal analytics integration.</li><li>The production sitemap includes both legal pages; the web build copies them with the application assets.</li></ul><p><strong>Verification boundary:</strong> this is a product-accurate informational notice based on the current repository implementation, not a legal opinion. Operator identity/contact details and applicable jurisdictional language should be reviewed before production publication. Browser-level visual and keyboard testing remains required.</p>`,30)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};